import {createWorld} from './world.mjs';
import {createShireAmbience} from './ambience.mjs';
import {replyToCharacter,STORY_WINDOW} from './conversation.mjs';
import {portraitSVG} from './portraits.mjs';
import {SAVE_KEY,NPCS,APPLES,frameDelta,freshState,restoreState,objective,nearestInteractable,talk,act,collect,dialogue,LORE} from './simulation.mjs';
const $=s=>document.querySelector(s),canvas=$('#game');
let engine,scene,world,state,started=false,activeNPC=null,journalOpen=false,yaw=0,pitch=.44,zoom=7.8,keys=new Set(),drag=null,joystick={x:0,y:0},toastTimer,saveTimer=0,time=0,soundEnabled=false,audio=null,audioTimer=null,destination=null,spokenText='';
const errors=[],telemetry={frames:0,seconds:0,collisions:0,interactions:0,collects:0,saves:0};
window.addEventListener('unhandledrejection',e=>fatal(e.reason?.message||String(e.reason)));
function fatal(message){errors.push(message);$('#loading').hidden=true;$('#fatal-text').textContent=message;$('#fatal').hidden=false;}
function readSave(){try{return restoreState(localStorage.getItem(SAVE_KEY));}catch{return freshState();}}
function save(){state.position={x:world.body.position.x,z:world.body.position.z};try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));telemetry.saves++;}catch{notify('الحفظ غير متاح في هذا المتصفّح');}}
function notify(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3500);}
function refresh(){ $('#objective').textContent=objective(state);$('#quest-progress').querySelectorAll('i').forEach((e,i)=>e.classList.toggle('done',i<state.stage));for(const a of world.apples)a.root.setEnabled(!state.apples.includes(a.id));$('#journal-objective').textContent=objective(state);$('#checklist').replaceChildren(...['قابل بيلبو','اسأل سام عن التحضيرات','اجمع ثلاث تفّاحات','أعد السلة إلى سام','ارجع إلى بيلبو'].map((t,i)=>{const li=document.createElement('li');li.textContent=(i<state.stage?'✓  ':'○  ')+t;li.className=i<state.stage?'checked':'';return li;}));}
function closeDialogue(){window.speechSynthesis?.cancel();spokenText='';activeNPC=null;$('#dialogue').hidden=true;$('#npc-chat-input').value='';$('#chat-log').replaceChildren();keys.clear();canvas.focus();}
function present(id,custom){const newCharacter=activeNPC!==id;const npc=NPCS.find(n=>n.id===id);const content=custom||dialogue(state,id);activeNPC=id;keys.clear();destination=null;$('#dialogue').hidden=false;$('#speaker').textContent=npc.name;$('#portrait').innerHTML=portraitSVG(id);$('#dialogue-text').textContent=content.text;spokenText=content.text;if(newCharacter){$('#chat-log').replaceChildren();$('#npc-chat-input').value='';}$('#choices').replaceChildren(...content.options.map(([label,action])=>{const button=document.createElement('button');button.textContent=label;button.onclick=()=>choose(action);return button;}));$('#choices button')?.focus();}
function sendChat(){if(!activeNPC)return;const input=$('#npc-chat-input');const question=input.value.trim().slice(0,170);if(!question)return;const response=replyToCharacter(state,activeNPC,question);spokenText=response.text;const log=$('#chat-log');for(const [kind,text] of [['player',question],['npc',response.text]]){const line=document.createElement('p');line.className='chat-'+kind;line.textContent=text;log.append(line);}input.value='';log.scrollTop=log.scrollHeight;save();}
function choose(action){if(action==='close'){closeDialogue();return;}if(LORE[action]){present(activeNPC,{text:LORE[action],options:[['شكرًا، نكمل حديثنا.','back'],['إلى اللقاء.','close']]});return;}if(action==='back'){present(activeNPC);return;}const changed=act(state,action);if(changed){refresh();save();notify(state.completed?'اكتملت رحلتك الأولى · أهلًا بك في الشاير':objective(state));}closeDialogue();}
function interact(){if(!started||activeNPC||journalOpen)return;const near=nearestInteractable(state,world.body.position);if(!near)return;if(near.id.startsWith('apple')){if(collect(state,near.id,world.body.position)){telemetry.collects++;refresh();save();notify(state.stage===3?'اكتملت السلة! ارجع إلى سام':`تفّاحة في السلة · ${state.apples.length}/3`);}return;}talk(state,near.id);telemetry.interactions++;save();present(near.id);}
function showJournal(){if(!started||activeNPC)return;keys.clear();destination=null;journalOpen=true;$('#journal').hidden=false;refresh();$('#journal-close').focus();}
function closeJournal(){journalOpen=false;$('#journal').hidden=true;canvas.focus();}
function speakDialogue(){const synthesizer=window.speechSynthesis,Utterance=window.SpeechSynthesisUtterance;if(!activeNPC||!spokenText)return;if(!synthesizer||!Utterance){notify('القراءة العربية غير مدعومة في هذا المتصفح');return;}synthesizer.cancel();const utterance=new Utterance(spokenText.slice(0,900));utterance.lang='ar';utterance.rate=activeNPC==='gandalf'?.86:activeNPC==='frodo'?1.06:.96;utterance.pitch=activeNPC==='gandalf'?.85:activeNPC==='frodo'?1.1:1;const voices=synthesizer.getVoices?.()||[];utterance.voice=voices.find(v=>v.lang?.toLowerCase().startsWith('ar'))||null;synthesizer.speak(utterance);}
function setupInput(){
 window.addEventListener('keydown',e=>{if(e.target instanceof Element&&e.target.closest('input,textarea')){if(e.code==='Escape')closeDialogue();return;}if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(e.code==='Escape'){if(activeNPC)closeDialogue();if(journalOpen)closeJournal();return;}if(e.repeat)return;if(e.code==='KeyE'){interact();return;}if(e.code==='KeyJ'){journalOpen?closeJournal():showJournal();return;}keys.add(e.code);destination=null;});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();joystick.x=joystick.y=0;drag=null;});
 canvas.addEventListener('pointerdown',e=>{if(activeNPC||journalOpen)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false};canvas.setPointerCapture(e.pointerId);canvas.focus();});
 canvas.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>6)drag.moved=true;yaw-=dx*.005;pitch=Math.max(.2,Math.min(.95,pitch+dy*.003));drag.x=e.clientX;drag.y=e.clientY;});
 canvas.addEventListener('pointerup',e=>{if(!drag||drag.id!==e.pointerId)return;const moved=drag.moved;drag=null;if(!moved&&started){const pick=scene.pick(scene.pointerX,scene.pointerY,m=>m===world.ground);if(pick?.hit){const p=pick.pickedPoint;if(p.x>-31&&p.x<31&&p.z>-23&&p.z<32){destination={x:p.x,z:p.z};notify('امشِ إلى المكان المحدّد · استخدم الأسهم لإلغاء المسار');}}}});canvas.addEventListener('pointercancel',()=>drag=null);
 canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(4.5,Math.min(12,zoom+e.deltaY*.007));},{passive:false});
 const joy=$('#joystick'),stick=$('#stick');let joyId=null;function joyMove(e){const r=joy.getBoundingClientRect();let dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2;const len=Math.hypot(dx,dy),max=35;if(len>max){dx*=max/len;dy*=max/len;}joystick={x:dx/max,y:-dy/max};stick.style.transform=`translate(${dx}px,${dy}px)`;destination=null;}
 joy.addEventListener('pointerdown',e=>{joyId=e.pointerId;joy.setPointerCapture(e.pointerId);joyMove(e);});joy.addEventListener('pointermove',e=>{if(e.pointerId===joyId)joyMove(e);});for(const event of ['pointerup','pointercancel','lostpointercapture'])joy.addEventListener(event,()=>{joyId=null;joystick={x:0,y:0};stick.style.transform='';});
 $('#npc-chat-form').addEventListener('submit',e=>{e.preventDefault();sendChat();});$('#npc-voice').onclick=speakDialogue;$('#interact').onclick=interact;$('#dialogue-close').onclick=closeDialogue;$('#journal-open').onclick=showJournal;$('#journal-close').onclick=closeJournal;$('#return').onclick=closeJournal;
 $('#reset').onclick=()=>{if(!confirm('تبدأ من جديد؟ سيتم استبدال تقدّمك المحفوظ على هذا المتصفّح.'))return;state=freshState();world.body.position.set(0,.72,-15);yaw=0;refresh();save();closeJournal();notify('بدأ صباح جديد');};
 let low=matchMedia('(pointer:coarse)').matches;function quality(){engine.setHardwareScalingLevel(low?Math.max(1.5,devicePixelRatio):Math.max(1,devicePixelRatio/1.5));if(world.shadow)world.shadow.getShadowMap().refreshRate=low?2:1;$('#quality').textContent=low?'جودة خفيفة':'جودة عادية';engine.resize();}$('#quality').onclick=()=>{low=!low;quality();};quality();
 $('#sound').onclick=toggleSound;window.addEventListener('resize',()=>engine.resize());document.addEventListener('visibilitychange',()=>{keys.clear();joystick.x=joystick.y=0;if(document.hidden&&started)save();if(audio)document.hidden?audio.suspend():soundEnabled&&audio.resume();});window.addEventListener('pagehide',()=>{if(started)save();});
}
async function toggleSound(){soundEnabled=!soundEnabled;$('#sound').textContent=soundEnabled?'♫ الأجواء مفعّلة':'♫';$('#sound').setAttribute('aria-label',soundEnabled?'إيقاف أصوات الشاير':'تشغيل أصوات الشاير');if(!soundEnabled){await audio?.stop();return;}const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio){soundEnabled=false;notify('الصوت غير مدعوم بهذا المتصفّح');return;}try{if(!audio)audio=createShireAmbience(Audio);await audio.start();notify('أجواء الشاير: عصافير وألحان هادئة أصلية');}catch{soundEnabled=false;$('#sound').textContent='♫';notify('تعذّر تشغيل الصوت على هذا الجهاز');}}
function animate(dt){time+=dt;const B=window.BABYLON,V=B.Vector3;const blocked=!started||!!activeNPC||journalOpen;let moving=false;
 if(!blocked){let forward=(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0)+joystick.y;let strafe=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)+joystick.x;let dx=Math.sin(yaw)*forward+Math.cos(yaw)*strafe,dz=Math.cos(yaw)*forward-Math.sin(yaw)*strafe;
 if(destination){dx=destination.x-world.body.position.x;dz=destination.z-world.body.position.z;if(Math.hypot(dx,dz)<.3){destination=null;dx=dz=0;}}
 const len=Math.hypot(dx,dz),speed=keys.has('ShiftLeft')?4.8:2.9;if(len>.05){dx/=len;dz/=len;moving=true;const desired=Math.atan2(dx,dz)+Math.PI;let diff=Math.atan2(Math.sin(desired-world.player.root.rotation.y),Math.cos(desired-world.player.root.rotation.y));world.player.root.rotation.y+=diff*Math.min(1,dt*10);}
 const before=world.body.position.clone();world.body.moveWithCollisions(new V(moving?dx*speed*dt:0,-.12,moving?dz*speed*dt:0));if(moving&&V.Distance(before,world.body.position)<speed*dt*.2){telemetry.collisions++;if(destination)destination=null;}
 if(world.body.position.y<-.5||!Number.isFinite(world.body.position.x)){world.body.position.set(0,.72,-15);destination=null;notify('رجعنا إلى بداية الطريق');}
 saveTimer+=dt;if(saveTimer>3){save();saveTimer=0;}
 }
 world.player.root.position.set(world.body.position.x,world.body.position.y-.7+(moving?Math.sin(time*15)*.035:0),world.body.position.z);
 for(const c of world.characters){if(c.id==='player'){const gait=moving?Math.sin(time*11)*.48:0;c.left.rotation.x=moving?-gait:Math.sin(time*1.4)*.035;c.right.rotation.x=-c.left.rotation.x;if(c.leftLeg){c.leftLeg.rotation.x=gait;c.rightLeg.rotation.x=-gait;}continue;}const phase=time*1.15+c.root.uniqueId;const speaking=activeNPC===c.id;c.root.position.y=Math.sin(phase)*.014;c.left.rotation.x=Math.sin(phase)*.11+(c.id==='sam'?Math.sin(time*.42)*.14:0);c.right.rotation.x=Math.sin(phase+.9)*-.1+(speaking?Math.sin(time*2)*.17:0);c.head.rotation.y=Math.sin(time*.62+c.root.uniqueId)*.065;c.head.rotation.x=Math.sin(time*.47+c.root.uniqueId)*.025;if(c.leftLeg){c.leftLeg.rotation.x=Math.sin(phase*.6)*.014;c.rightLeg.rotation.x=-c.leftLeg.rotation.x;}if(speaking){const dx=world.body.position.x-c.root.position.x,dz=world.body.position.z-c.root.position.z;c.root.rotation.y=Math.atan2(dx,dz)+Math.PI;}}
 for(const a of world.apples){a.root.position.y=.4+Math.sin(time*2.5+a.root.uniqueId)*.06;a.root.rotation.y=time*.4;a.halo.scaling.setAll(1+Math.sin(time*3)*.1);}
 for(const bird of world.birds){const t=time*.13+bird.phase;bird.root.position.set(Math.cos(t)*21,10+Math.sin(t*2),Math.sin(t)*15+8);bird.root.rotation.y=-t;bird.root.rotation.z=Math.sin(time*8+bird.phase)*.18;}
 const target=new V(world.body.position.x,1.25,world.body.position.z);let desired;
 if(!started){desired=new V(1+Math.sin(time*.06)*1.6,5.2,-23);scene.activeCamera.position.copyFrom(desired);scene.activeCamera.setTarget(new V(0,2,4));}
 else {desired=target.add(new V(-Math.sin(yaw)*zoom,Math.sin(pitch)*zoom+.8,-Math.cos(yaw)*zoom));const ray=new B.Ray(target,desired.subtract(target).normalize(),V.Distance(target,desired));const hit=scene.pickWithRay(ray,m=>world.colliders.includes(m));if(hit?.hit&&hit.distance>1.4)desired=target.add(ray.direction.scale(Math.max(1.5,hit.distance-.35)));scene.activeCamera.position=B.Vector3.Lerp(scene.activeCamera.position,desired,1-Math.exp(-dt*7));scene.activeCamera.setTarget(target);}
 if(started&&!activeNPC&&!journalOpen){const near=nearestInteractable(state,world.body.position);$('#interaction').hidden=!near;if(near)$('#interact span').textContent=near.id.startsWith('apple')?'التقط التفّاحة':'تحدّث مع '+near.name;}else $('#interaction').hidden=true;
 for(const npc of NPCS){const el=$('#label-'+npc.id),character=world.characters.find(c=>c.id===npc.id);const p=character.root.position.add(new V(0,npc.id==='gandalf'?3.5:2.25,0)),distance=V.Distance(scene.activeCamera.position,p);const projected=V.Project(p,B.Matrix.Identity(),scene.getTransformMatrix(),scene.activeCamera.viewport.toGlobal(engine.getRenderWidth(),engine.getRenderHeight()));const rect=canvas.getBoundingClientRect();el.hidden=!started||!!activeNPC||journalOpen||distance>22||projected.z<0||projected.z>1;el.style.left=projected.x/engine.getRenderWidth()*rect.width+'px';el.style.top=projected.y/engine.getRenderHeight()*rect.height+'px';}
 if(state.completed){world.sun.diffuse=B.Color3.Lerp(world.sun.diffuse,new B.Color3(1,.82,.55),dt*.1);}
 telemetry.frames++;telemetry.seconds+=dt;if(new URLSearchParams(location.search).has('qa')){const diag=$('#qa-diagnostics');if(diag)diag.textContent=JSON.stringify(snapshot());}
}
function snapshot(){return {version:'0.2.1',storyWindow:STORY_WINDOW.id,state:structuredClone(state),position:{x:world?.body.position.x,y:world?.body.position.y,z:world?.body.position.z},started,activeNPC,journalOpen,camera:{yaw,pitch,zoom},fps:Math.round(engine?.getFps()||0),meshes:scene?.meshes.length,triangles:scene?scene.meshes.reduce((n,m)=>n+m.getTotalIndices()/3,0):0,telemetry:{...telemetry},errors:[...errors],world:world?.stats};}
async function boot(){try{const B=window.BABYLON;if(!B)throw Error('تعذّر تحميل محرك Babylon.js. أعد تحميل الصفحة.');engine=new B.Engine(canvas,true,{preserveDrawingBuffer:true,stencil:true,powerPreference:'default'});engine.loadingScreen={displayLoadingUI(){},hideLoadingUI(){}};scene=new B.Scene(engine);const camera=new B.UniversalCamera('third-person camera',new B.Vector3(0,5,-23),scene);camera.minZ=.15;camera.maxZ=200;camera.fov=.87;camera.inputs.clear();world=createWorld(B,scene);state=readSave();world.body.position.set(state.position.x,.72,state.position.z);world.body.onCollide=()=>telemetry.collisions++;
 for(const npc of NPCS){const label=document.createElement('span');label.className='npc-label';label.id='label-'+npc.id;label.textContent=npc.name;label.hidden=true;$('#npc-labels').append(label);}
 if(new URLSearchParams(location.search).has('qa')){const pre=document.createElement('pre');pre.id='qa-diagnostics';pre.style.cssText='position:fixed;left:5px;bottom:2px;max-width:95%;font:8px monospace;color:white;background:#0008;pointer-events:none;z-index:2;direction:ltr;white-space:pre-wrap;max-height:36px;overflow:hidden';document.body.append(pre);}
 refresh();setupInput();await scene.whenReadyAsync();$('#loading').hidden=true;$('#welcome').hidden=false;$('#resume-note').hidden=state.stage===0;$('#start').textContent=state.stage>0?'أكمل الرحلة ←':'ابدأ الرحلة ←';$('#start').onclick=()=>{started=true;$('#welcome').hidden=true;$('#hud').hidden=false;canvas.focus();notify('مرحبًا في الشاير · قابل بيلبو قرب الباب الأخضر');};
 canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();notify('توقّف عرض الرسومات مؤقتًا. نحاول استعادته…');});canvas.addEventListener('webglcontextrestored',()=>notify('عاد عرض الرسومات'));engine.runRenderLoop(()=>{if(document.hidden)return;const dt=frameDelta(engine.getDeltaTime());animate(dt);scene.render();});window.__SHIRE__=Object.freeze((new URLSearchParams(location.search).has('qa')&&['localhost','127.0.0.1'].includes(location.hostname))?{snapshot,qaReposition:(x,z)=>{if(!started||![x,z].every(Number.isFinite)||Math.abs(x)>30||z< -23||z>31)throw Error('Invalid QA location');world.body.position.set(x,.72,z);destination=null;save();return snapshot();}}:{snapshot});
}catch(e){fatal(e.message||String(e));}}
boot();
